mapper.select:
SELECT id AS electricCardId, card_type AS cardType, single_limit AS singleLimit, card_number AS cardNumber, physical_card AS physicalCard, cardholder AS cardHolder, license_number AS licenseNumber, current_balance AS currentBalance, create_time AS createTime, state FROM b_electric_card WHERE 1 = 1
AND id = #{electricCardId}
AND cardholder LIKE CONCAT('%', #{cardHolder}, '%')
AND card_number LIKE CONCAT('%', #{cardNumber}, '%')
AND create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY create_time DESC
